use std::{env,fs,path::PathBuf};
fn main(){
 let root=PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
 let source=root.join("../native-engine/src/search.rs");println!("cargo:rerun-if-changed={}",source.display());
 let mut s=fs::read_to_string(source).unwrap().replace("\r\n","\n");
 // Root utility translates null windows; leaf wall utility and bounded arrival
 // continuations are separately evaluated inside the candidate engine.
 for(from,to) in [
  ("if pos.left == [0, 0] {", "if self.apply_pawn_finish(&pos,&mut out,deadline,&cancel) { return out; }\n        if pos.left == [0, 0] {"),
  ("if !cancel.load(Ordering::Relaxed) {\n            // A directly proven", "if !cancel.load(Ordering::Relaxed) {\n            self.apply_pawn_finish(&pos,&mut out,deadline,&cancel);\n            // A directly proven"),
  ("out.result.pv = vec![decode(action)];", "if !pawn_finish_preferred(&out,distance.saturating_add(1)) {\n                out.result.pv = vec![decode(action)];"),
  ("out.outcome = Some(1);", "out.outcome = Some(1);\n                out.win_proof=Some(WinProof{kind:\"last-wall-ending\",guaranteed_plies:distance.saturating_add(1),shortest_win_proven:false,wall_spent:true});\n                }"),
  ("struct SharedSearch {", "struct SharedSearch {\n    root_wall_streak: AtomicUsize,\n    root_wall_run: Mutex<Vec<WallRunEntry>>,\n    root_defense_reply: AtomicUsize,\n    root_recent_pawns: Mutex<Vec<usize>>,\n    goal_root_active: AtomicBool,\n    goal_frontier: AtomicU64,"),
  ("            profile: 0,", "            root_wall_streak: AtomicUsize::new(0),\n            root_wall_run: Mutex::new(vec![]),\n            root_defense_reply: AtomicUsize::new(209),\n            root_recent_pawns: Mutex::new(vec![]),\n            goal_root_active: AtomicBool::new(false),\n            goal_frontier: AtomicU64::new(0),\n            profile: 0,"),
  ("for depth in 1..=max_depth.clamp(1, 64) {", "for depth in 1..=max_depth.clamp(1, 64) {\n            self.shared.goal_frontier.store((depth+2).min(14) as u64, Ordering::Relaxed);"),
  ("if ply < 12\n                && p.moves(1 - p.turn)", "if goal_deep_enabled() && self.shared.goal_root_active.load(Ordering::Relaxed) && ply < self.shared.goal_frontier.load(Ordering::Relaxed) as usize && goal_window(p)\n                || ply < 12\n                && p.moves(1 - p.turn)"),
  ("let protected = self.shared.is_critical(p, a);", "let protected = self.shared.is_critical(p, a) || goal_deep_enabled() && self.shared.goal_root_active.load(Ordering::Relaxed) && depth>=3 && i>=8 && goal_critical(p, a);"),
  ("((theirs - enemy) - (mine - own)) * 1600 - 130", "((theirs - enemy) - (mine - own)) * 1600 - 130 + if self.goal_root_active.load(Ordering::Relaxed) && enemy<=3 && theirs>enemy {1200}else{0}"),
  ("self.static_score(&mut mirror_position(p))", "self.goal_score(&mut mirror_position(p))"),
  ("self.static_score(p)", "self.goal_score(p)"),
  ("return Ok(self.shared.evaluate(p));", "if arrival_window(p){return self.arrival_frontier(p,3,&mut 6,path);}\n                return Ok(self.shared.evaluate(p));"),
  ("pub struct NativeOutput {","pub struct NativeOutput {\n    #[serde(skip_serializing_if = \"Option::is_none\")]\n    pub reserve_defense: Option<ReserveDefense>,\n    #[serde(skip_serializing_if = \"Option::is_none\")]\n    pub weak_wall_consumption: Option<WeakWallConsumption>,\n    #[serde(skip_serializing_if = \"Option::is_none\")]\n    pub connection_risk: Option<ConnectionRisk>,\n    #[serde(skip_serializing_if = \"Option::is_none\")]\n    pub threat_defense: Option<ThreatDefense>,\n    #[serde(skip_serializing_if = \"Option::is_none\")]\n    pub race_assessment: Option<RaceAssessment>,\n    #[serde(skip_serializing_if = \"Option::is_none\")]\n    pub win_proof: Option<WinProof>,\n    #[serde(skip_serializing_if = \"Option::is_none\")]\n    pub goal_safety: Option<GoalSafety>,\n    #[serde(skip_serializing_if = \"Option::is_none\")]\n    pub pressure: Option<PressureFeatures>,"),
  ("let mut out = NativeOutput {","let mut out = NativeOutput {\n            reserve_defense: None,\n            weak_wall_consumption: None,\n            connection_risk: None,\n            threat_defense: None,\n            race_assessment: None,\n            win_proof: None,\n            goal_safety: None,\n            pressure: None,"),
  ("if s.winner.is_some() {", "let goal_active=goal_enabled() && goal_window(&pos) && pos.distance(pos.turn,false)<=3 && pos.left[1-pos.turn]>0;\n        if self.shared.goal_root_active.swap(goal_active,Ordering::Relaxed)!=goal_active {for cache in &self.shared.moves{cache.write().unwrap().clear();}}\n        if goal_enabled() { out.goal_safety=Some(self.shared.goal_details(&mut pos)); }\n        if s.winner.is_some() {"),
  ("let root_key = pos.key();","let root_key = pos.key();\n        let base_biases = pressure_biases(&mut pos, deadline, &cancel);\n        let tempo = tempo_biases(&mut pos, base_biases, deadline, &cancel);\n        let goal_bias = goal_biases(&mut pos, tempo, deadline, &cancel);\n        let (reserve_bias, reserve) = defense_reserve_biases(&mut pos, goal_bias, deadline, &cancel);\n        let observed_run=self.shared.root_wall_run.lock().unwrap().clone();\n        let (weak_bias,weak)=weak_wall_biases(&mut pos,reserve_bias,&reserve,&observed_run,self.shared.root_wall_streak.load(Ordering::Relaxed),deadline,&cancel);\n        let (chain_bias,chain)=connection_biases(&mut pos,weak_bias,deadline,&cancel);\n        let (defense_bias,defense)=threat_defense_biases(&pos,chain_bias,deadline,&cancel,{let a=self.shared.root_defense_reply.load(Ordering::Relaxed);if a<209{Some(a as u16)}else{None}});\n        let chosen_bias=if defense.active && defense.complete {defense_bias}else{chain_bias};\n        let biases=self.progress_biases(&pos,race_biases(chosen_bias,out.race_assessment.as_ref()));\n        out.threat_defense=Some(defense.clone());\n        out.reserve_defense=Some(reserve);out.weak_wall_consumption=Some(weak);out.connection_risk=Some(chain);"),
  ("let roots = &roots;", "let roots = &roots; let defense = &defense;"),
  ("let protected = searcher.shared.is_critical(pos, a);", "let protected = searcher.shared.is_critical(pos, a) || defense.protect(a);"),
  ("let score = -value;","let score = pressure_adjust(-value, biases[first as usize], 0);"),
  ("let base = alpha.load(Ordering::Acquire);","let global_base = alpha.load(Ordering::Acquire);\n                            let bias = if global_base.abs() > WIN - 500 { 0 } else { biases[a as usize] };\n                            let base = global_base - bias;"),
  ("let Ok(score) = result else {","let Ok(raw_score) = result else {"),
  ("let mut record = best.lock().unwrap();","let score = pressure_adjust(raw_score, bias, global_base);\n                                let mut record = best.lock().unwrap();"),
  ("if score > record.1 {", "if score > record.1 || goal_enabled() && score == record.1 && score.abs()>WIN-500 && searcher.shared.prefer_root_tie(pos,a,record.0) {"),
  ("Ok::<i32, ()>(score)", "if goal_enabled() && score == base && score.abs()>WIN-500 { let preferred={let r=best.lock().unwrap();score==r.1 && searcher.shared.prefer_root_tie(pos,a,r.0)}; if preferred {score=-searcher.negamax(&mut p,depth as i32-1,-INF,INF,1,&mut vec![root_key])?;} }\n                                Ok::<i32, ()>(score)"),
  ("progress(&out);","self.prefer_exact_output(s,&mut out); if let Some(details)=out.threat_defense.as_mut(){details.review_selected(s,out.result.pv.first(),deadline,&cancel);} if let Some(details)=out.connection_risk.as_mut(){details.select(out.result.pv.first());} if let Some(details)=out.weak_wall_consumption.as_mut(){details.select(out.result.pv.first());} if let Some(details)=out.reserve_defense.as_mut(){details.select(out.result.pv.first());} out.pressure = pressure_advice(s, out.result.pv.first());\n            progress(&out);"),
  ("if self.shared.profile == 0 {","if pressure_enabled() { if goal_enabled() { \"5.3 + goal safety 0.4\" } else if tempo_enabled() { \"5.3 + wall tempo 0.3\" } else { \"5.3 + immediate pressure 0.2\" } } else if self.shared.profile == 0 {"),
  ("return out;","self.prefer_exact_output(s,&mut out); if let Some(details)=out.threat_defense.as_mut(){details.review_selected(s,out.result.pv.first(),deadline,&cancel);} if let Some(details)=out.connection_risk.as_mut(){details.select(out.result.pv.first());} if let Some(details)=out.weak_wall_consumption.as_mut(){details.select(out.result.pv.first());} if let Some(details)=out.reserve_defense.as_mut(){details.select(out.result.pv.first());} out.pressure = pressure_advice(s, out.result.pv.first()); out.result.elapsed_ms = now()-start; return out;"),
 ]{let count=s.matches(from).count();assert!(count>0,"missing patch {from}");if from!="return out;"{assert_eq!(count,1,"ambiguous patch {from}");}s=s.replace(from,to);}
 // The final expression follows all cancellation/endgame fallbacks.
 let tail="        out\n    }\n}";assert_eq!(s.matches(tail).count(),1);s=s.replace(tail,"        self.prefer_exact_output(s,&mut out); if let Some(details)=out.threat_defense.as_mut(){details.review_selected(s,out.result.pv.first(),deadline,&cancel);} if let Some(details)=out.connection_risk.as_mut(){details.select(out.result.pv.first());} if let Some(details)=out.weak_wall_consumption.as_mut(){details.select(out.result.pv.first());} if let Some(details)=out.reserve_defense.as_mut(){details.select(out.result.pv.first());} out.pressure = pressure_advice(s, out.result.pv.first());\n        out.result.elapsed_ms = now()-start;\n        out\n    }\n}");
 let output=PathBuf::from(env::var("OUT_DIR").unwrap());fs::write(output.join("search.rs"),s).unwrap();
 let main_file=root.join("../native-engine/src/main.rs");println!("cargo:rerun-if-changed={}",main_file.display());let mut m=fs::read_to_string(main_file).unwrap().replace("\r\n","\n").replace("use quoridor_native::{NativeEngine, State};","use quoridor_pressure::{NativeEngine, State, explain_pressure, explain_tempo, explain_goal, explain_connection, explain_defense};");
 m=m.replace("let r = engine.search(","engine.set_wall_run(&v[\"state\"]); engine.set_recent_pawns(&v[\"state\"][\"recentPawnSquares\"]); engine.set_defense_reply(v[\"state\"][\"defenseReply\"].clone()); engine.set_wall_streak(v[\"state\"][\"wallStreak\"].as_u64().unwrap_or(0).min(10) as usize); let r = engine.search(");
 let defense_marker="            \"health\" => emit(";m=m.replace(defense_marker,&("            \"defense\" => emit(&output, serde_json::json!({\"id\":v[\"id\"],\"done\":true,\"diagnostics\":explain_defense(v.clone())})),\n".to_owned()+defense_marker));
 let chain_marker="            \"health\" => emit(";m=m.replace(chain_marker,&("            \"connection\" => emit(&output, serde_json::json!({\"id\":v[\"id\"],\"done\":true,\"diagnostics\":explain_connection(v.clone())})),\n".to_owned()+chain_marker));
 let marker="            \"health\" => emit(";assert_eq!(m.matches(marker).count(),1);m=m.replace(marker,&("            \"goal\" => emit(&output, serde_json::json!({\"id\":v[\"id\"],\"done\":true,\"diagnostics\":explain_goal(v.clone())})),\n".to_owned()+"            \"tempo\" => emit(&output, serde_json::json!({\"id\":v[\"id\"],\"done\":true,\"diagnostics\":explain_tempo(v[\"state\"].clone())})),\n            \"explain\" => emit(&output, serde_json::json!({\"id\":v[\"id\"],\"done\":true,\"diagnostics\":explain_pressure(v[\"state\"].clone())})),\n            \"health\" => emit("));fs::write(output.join("main.rs"),m).unwrap();
}
